import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, createUserExamData } from '../services/api'; // Updated import

const AssociatedFranchises = () => {
  const [examData, setExamData] = useState({
    franchiseId: '', // This will be populated with the user's associated franchiseId
    examName: '',
    date: '',
    studentsAttended: '',
  });
  const [franchiseName, setFranchiseName] = useState(''); // New state to store franchise name
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchUserFranchise = async () => {
      setLoading(true);
      try {
        const data = await getAssociatedFranchises(); // Use the correct function
        if (data && data.length > 0) {
          setFranchiseName(data[0].name); // Assuming the franchise has a 'name' property
          setExamData((prevData) => ({ ...prevData, franchiseId: data[0]._id })); // Assuming user can have multiple franchises, pick the first one
        } else {
          setError('No associated franchise found for the user.');
        }
      } catch (error) {
        setError('Failed to fetch the associated franchise.');
      } finally {
        setLoading(false);
      }
    };

    fetchUserFranchise();
  }, []); // Empty dependency array ensures this runs only once

  const handleExamDataChange = (e) => {
    setExamData({
      ...examData,
      [e.target.name]: e.target.value,
    });
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();

    // Validate the date
    if (!examData.date) {
      setError('Please provide the exam date.');
      return;
    }

    // Ensure the date is valid
    const examDate = new Date(examData.date);
    if (isNaN(examDate.getTime())) {
      setError('Invalid date format.');
      return;
    }

    // Validate studentsAttended (should be a number)
    if (isNaN(examData.studentsAttended) || examData.studentsAttended <= 0) {
      setError('Please provide a valid number of students attended.');
      return;
    }

    setLoading(true);
    try {
      const formattedDate = examDate.toISOString().split('T')[0]; // Format the date to YYYY-MM-DD
      await createUserExamData({ ...examData, date: formattedDate });
      setSuccess('Exam data created successfully!');
      setExamData({ franchiseId: '', examName: '', date: '', studentsAttended: '' });
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000); // Success message disappears after 3 seconds
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>
        Associated Franchise: {franchiseName || 'Loading...'}
      </h2>

      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData} style={styles.form}>
        {/* Franchise ID is now populated automatically based on the user's associated franchise */}
        <div style={styles.formGroup}>
          <label htmlFor="examName" style={styles.label}>Exam Name</label>
          <input
            type="text"
            name="examName"
            value={examData.examName}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="date" style={styles.label}>Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="studentsAttended" style={styles.label}>Students Attended</label>
          <input
            type="number"
            name="studentsAttended"
            value={examData.studentsAttended}
            onChange={handleExamDataChange}
            required
            min="1" // Ensure at least one student is entered
            style={styles.input}
          />
        </div>

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

// CSS styles in JS format
const styles = {
  container: {
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
  },
  header: {
    fontSize: '2rem',
    textAlign: 'center',
    marginBottom: '20px',
  },
  formTitle: {
    fontSize: '1.5rem',
    marginBottom: '15px',
    textAlign: 'center',
  },
  form: {
    width: '100%',
    maxWidth: '500px',
    padding: '20px',
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
  },
  formGroup: {
    marginBottom: '15px',
  },
  label: {
    display: 'block',
    marginBottom: '8px',
    fontSize: '1rem',
  },
  input: {
    width: '100%',
    padding: '10px',
    fontSize: '1rem',
    border: '1px solid #ccc',
    borderRadius: '4px',
    boxSizing: 'border-box',
  },
  submitButton: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '5px',
    cursor: 'pointer',
    fontSize: '1.1rem',
    transition: 'background-color 0.3s ease',
  },
  submitButtonDisabled: {
    backgroundColor: '#ccc',
  },
  loading: {
    textAlign: 'center',
    fontSize: '1.2rem',
    color: '#007bff',
  },
  error: {
    color: 'red',
    fontSize: '1.1rem',
    textAlign: 'center',
  },
  success: {
    color: 'green',
    fontSize: '1.1rem',
    textAlign: 'center',
  },
};

export default AssociatedFranchises;
